/**
 * src/agents/tx-2-imp-1/prompts/action-04.ts
 * 
 * Contract: tx_2_imp_1
 * Action 4: 部長に通知メールを送信する
 * 
 * このアクションは、未提出者と遅延者の一覧を部長に通知するメールを生成します。
 */

export const ACTION_04_PROMPT_VERSION = "1.0.0";

export interface Action04PromptInput {
  /**
   * 未提出者の一覧
   */
  nonSubmitters: Array<{
    employeeId: string;
    employeeName: string;
    department: string;
  }>;

  /**
   * 遅延者の一覧
   */
  delayedSubmitters: Array<{
    employeeId: string;
    employeeName: string;
    department: string;
    submittedAt: string;
    deadline: string;
    delayMinutes: number;
  }>;

  /**
   * 部長のメールアドレス
   */
  managerEmail: string;

  /**
   * 部長の名前
   */
  managerName: string;

  /**
   * 報告対象日付（YYYY-MM-DD形式）
   */
  reportDate: string;

  /**
   * 総従業員数
   */
  totalEmployees: number;

  /**
   * 提出期限（HH:mm形式）
   */
  deadline: string;
}

export interface Action04PromptOutput {
  /**
   * 生成されたメール件名
   */
  subject: string;

  /**
   * 生成されたメール本文
   */
  body: string;

  /**
   * 送信対象のメールアドレス
   */
  recipientEmail: string;

  /**
   * 未提出者数
   */
  nonSubmitterCount: number;

  /**
   * 遅延者数
   */
  delayedSubmitterCount: number;

  /**
   * 提出完了者数
   */
  submittedCount: number;

  /**
   * 提出率（パーセンテージ）
   */
  submissionRate: number;
}

/**
 * Action 4: 部長に通知メールを送信するプロンプトを生成
 * 
 * 未提出者と遅延者の情報から、部長への通知メールを生成します。
 * メールには以下の情報を含めます：
 * - 報告対象日付
 * - 提出状況の集計（提出完了数、未提出数、遅延数）
 * - 提出率
 * - 未提出者の一覧（部門別に整理）
 * - 遅延者の一覧（遅延時間とともに記載）
 * - 推奨アクション
 * 
 * @param input - プロンプト生成に必要な入力情報
 * @returns 生成されたプロンプトと出力スキーマ
 */
export function buildAction04Prompt(
  input: Action04PromptInput
): {
  systemPrompt: string;
  userPrompt: string;
  outputSchema: Record<string, unknown>;
} {
  const submittedCount =
    input.totalEmployees -
    input.nonSubmitters.length -
    input.delayedSubmitters.length;
  const submissionRate = Math.round(
    ((submittedCount + input.delayedSubmitters.length) /
      input.totalEmployees) *
      100
  );

  const nonSubmittersByDept = input.nonSubmitters.reduce(
    (acc, emp) => {
      if (!acc[emp.department]) {
        acc[emp.department] = [];
      }
      acc[emp.department].push(emp);
      return acc;
    },
    {} as Record<string, typeof input.nonSubmitters>
  );

  const delayedSubmittersByDept = input.delayedSubmitters.reduce(
    (acc, emp) => {
      if (!acc[emp.department]) {
        acc[emp.department] = [];
      }
      acc[emp.department].push(emp);
      return acc;
    },
    {} as Record<string, typeof input.delayedSubmitters>
  );

  const systemPrompt = `あなたは朝会報告管理システムの通知メール生成エージェントです。
部長に対して、日報の提出状況に関する通知メールを生成します。

以下の要件に従ってメールを生成してください：
1. 件名は簡潔で、報告対象日付と提出状況を含める
2. 本文は以下の構成で作成：
   - 挨拶と報告対象日付の明記
   - 提出状況の集計（提出完了数、未提出数、遅延数、提出率）
   - 未提出者の一覧（部門別に整理）
   - 遅延者の一覧（遅延時間とともに記載）
   - 推奨アクション（催促の必要性など）
3. トーンは丁寧かつ簡潔に
4. 数値は見やすくフォーマット
5. 部長名を本文に含める`;

  const userPrompt = `以下の情報に基づいて、部長への通知メールを生成してください。

【報告対象日付】
${input.reportDate}

【提出期限】
${input.deadline}

【提出状況集計】
- 総従業員数: ${input.totalEmployees}名
- 提出完了: ${submittedCount}名
- 遅延提出: ${input.delayedSubmitters.length}名
- 未提出: ${input.nonSubmitters.length}名
- 提出率: ${submissionRate}%

【未提出者一覧（部門別）】
${
  Object.entries(nonSubmittersByDept).length > 0
    ? Object.entries(nonSubmittersByDept)
        .map(
          ([dept, emps]) =>
            `${dept}:\n${emps.map((e) => `  - ${e.employeeName} (${e.employeeId})`).join("\n")}`
        )
        .join("\n")
    : "なし"
}

【遅延者一覧（部門別）】
${
  Object.entries(delayedSubmittersByDept).length > 0
    ? Object.entries(delayedSubmittersByDept)
        .map(
          ([dept, emps]) =>
            `${dept}:\n${emps
              .map(
                (e) =>
                  `  - ${e.employeeName} (${e.employeeId}): ${e.delayMinutes}分遅延 (提出: ${e.submittedAt})`
              )
              .join("\n")}`
        )
        .join("\n")
    : "なし"
}

【送信先】
- メールアドレス: ${input.managerEmail}
- 部長名: ${input.managerName}

以下のJSON形式で出力してください：
{
  "subject": "メール件名",
  "body": "メール本文",
  "recipientEmail": "${input.managerEmail}",
  "nonSubmitterCount": ${input.nonSubmitters.length},
  "delayedSubmitterCount": ${input.delayedSubmitters.length},
  "submittedCount": ${submittedCount},
  "submissionRate": ${submissionRate}
}`;

  const outputSchema = {
    type: "object",
    properties: {
      subject: {
        type: "string",
        description: "メール件名",
      },
      body: {
        type: "string",
        description: "メール本文",
      },
      recipientEmail: {
        type: "string",
        description: "送信対象のメールアドレス",
      },
      nonSubmitterCount: {
        type: "number",
        description: "未提出者数",
      },
      delayedSubmitterCount: {
        type: "number",
        description: "遅延者数",
      },
      submittedCount: {
        type: "number",
        description: "提出完了者数",
      },
      submissionRate: {
        type: "number",
        description: "提出率（パーセンテージ）",
      },
    },
    required: [
      "subject",
      "body",
      "recipientEmail",
      "nonSubmitterCount",
      "delayedSubmitterCount",
      "submittedCount",
      "submissionRate",
    ],
  };

  return {
    systemPrompt,
    userPrompt,
    outputSchema,
  };
}
